-- ===== IMPORTACION DE PRODUCTOS =====
-- IMPORTACION DE LOS 1284 ARTICULOS EXISTENTES: SE PUEDE REPETIR SIN PISAR CAMBIOS DEL ADMIN.
-- En una base ya poblada, ejecutar solo si schema.sql y 02_ampliacion_comercial.sql existen.
-- Si la base esta vacia: usar 01_INSTALAR_LAFAVORITA_WEB.sql y no repetir este archivo.
BEGIN;
CREATE TABLE IF NOT EXISTS catalogo_origen_facturador (
 sku TEXT PRIMARY KEY,nombre_original TEXT NOT NULL,marca_propuesta TEXT NOT NULL DEFAULT '',
 categoria_propuesta TEXT NOT NULL REFERENCES categories(id),
 precio_origen NUMERIC(14,4) NOT NULL CHECK(precio_origen>=0),
 costo_compra_origen NUMERIC(14,4) CHECK(costo_compra_origen>=0),
 stock_almacen_origen NUMERIC(16,2),stock_minimo_origen NUMERIC(14,2),
 id_almacen_origen TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '',
 importado_el TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS presentaciones_adicionales (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
 nombre TEXT NOT NULL,cantidad_base NUMERIC(14,3) NOT NULL CHECK(cantidad_base>1),
 unidad_base TEXT NOT NULL DEFAULT 'unidad',exige_empaque_cerrado BOOLEAN NOT NULL DEFAULT FALSE,
 activa BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE(product_id,nombre),
 CHECK(unidad_base IN ('unidad','g','kg','ml','l','cm','m','mm','hoja','metro','rollo','pieza','set'))
);
CREATE TABLE IF NOT EXISTS precios_presentacion_sucursal (
 presentacion_id BIGINT NOT NULL REFERENCES presentaciones_adicionales(id) ON DELETE CASCADE,
 branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE CASCADE,
 precio NUMERIC(12,2) NOT NULL CHECK(precio>=0),
 stock_empaques INTEGER NOT NULL DEFAULT 0 CHECK(stock_empaques>=0),
 publicado BOOLEAN NOT NULL DEFAULT FALSE,
 PRIMARY KEY(presentacion_id,branch_id)
);
CREATE INDEX IF NOT EXISTS idx_presentaciones_producto ON presentaciones_adicionales(product_id);
CREATE OR REPLACE VIEW v_precios_catalogo_admin AS
 SELECT p.sku,p.name,p.brand,c.name AS categoria,b.name AS sucursal,o.price AS precio_soles,
 o.stock,o.min_stock,o.active AS publicado,p.image_url
 FROM products p JOIN categories c ON p.category_id=c.id
 JOIN offers o ON o.product_id=p.id JOIN branches b ON b.id=o.branch_id;
